"""Build a self-contained review tool with current original parts and source motion."""
from pathlib import Path
import json,base64
P=Path(__file__).resolve().parent;views=['S','SW','W','NW','N','NE','E','SE'];catalog={}
for v in views:
 d=json.loads((P/(('' if v=='W' else v+'-')+'walk-rig-contract.json')).read_text())
 d['images']={n:'data:image/png;base64,'+base64.b64encode((P/a['texture']).read_bytes()).decode() for n,a in d['definitions'].items()};catalog[v]=d
scripts='\n'.join((P/'inputs'/n).read_text() for n in ['sprite-mesh-player.js','sprite-articulated-player.js','sprite-clip-clock.cjs'])
html='''<!doctype html><html lang="th"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ท่าเดิน 8 มุม · ตรวจภาพเคลื่อนไหว</title><style>body{background:#20252d;color:#eee;font:16px system-ui;margin:24px;max-width:1080px}h1{font-size:24px}canvas{display:block;background:#292b30;max-width:100%;height:auto}button,select,input{font:inherit;margin:6px}input[type=range]{width:min(320px,70vw)}p{line-height:1.6}#status{min-height:28px}small{color:#c3ccd6}</style><h1>ตรวจท่าเดิน · 8 มุม</h1><p><select id="view" aria-label="มุมมอง"></select><button id="play" disabled>เล่น / หยุด</button><select id="speed"><option value="1">1×</option><option value="0.25">¼×</option></select><label><input id="travel" type="checkbox">เดินผ่านพื้น</label><label><input id="loop" type="checkbox" checked>วน</label></p><canvas id="c" width="512" height="576"></canvas><p><input id="frame" disabled type="range" min="0" max="79" value="0" aria-label="เฟรม"><span id="status">กำลังโหลด…</span></p><p><small>80 เฟรมที่ประเมินจากริกต่อรอบ 800 ms · ปรับเฟรมเพื่อตรวจภาพ หรือเปิดเดินผ่านพื้นเพื่อตรวจเท้าลงน้ำหนัก<br>ตัวอย่างวิจัยท่าเดิน · การตรวจชุดท่าอื่นและการเชื่อมต่อกับเกมยังไม่ครบ</small></p><script>__SCRIPTS__</script><script>
const catalog=__DATA__,$=id=>document.getElementById(id),ctx=$('c').getContext('2d');let D,view,clock,frame=0,last=null,serial=0,layers=new Map();
for(const v of Object.keys(catalog))$('view').add(new Option(v,v));
function poseAt(t){const k=Math.max(0,Math.min(256,t*256)),i=Math.min(255,Math.floor(k)),f=k-i,p={};for(const n of Object.keys(D.poses[0]))p[n]=D.poses[i][n].map((a,j)=>a*(1-f)+D.poses[i+1][n][j]*f);return p}
function offsetAt(t){const k=Math.max(0,Math.min(256,t*256)),i=Math.min(255,Math.floor(k)),f=k-i;return D.world_offsets[i].map((a,j)=>a*(1-f)+D.world_offsets[i+1][j]*f)}
function draw(t=clock.time/clock.total){const travel=$('travel').checked,width=travel?768:D.canvas[0],height=travel?768:D.canvas[1];if($('c').width!==width||$('c').height!==height){$('c').width=width;$('c').height=height}ctx.clearRect(0,0,width,height);const p=poseAt(t),o=travel?offsetAt(t):[0,0];p.output_offset=travel?[128+o[0],128+o[1]]:[0,0];for(const n of D.order){const m=layers.get(n);m.setViewport(width,height);m.draw(p);ctx.drawImage(m.canvas,0,0)}$('frame').value=frame;$('status').textContent=view+' · '+(frame+1)+'/80 · '+Math.round(clock.time)+' / 800 ms'}
function dispose(){for(const m of layers.values()){m.dispose();m.gl.getExtension('WEBGL_lose_context')?.loseContext()}layers.clear()}
async function choose(v){const token=++serial;window.READY=false;window.LOAD_ERROR=null;if(clock)clock.cancel();last=null;$('play').disabled=$('frame').disabled=true;dispose();ctx.clearRect(0,0,$('c').width,$('c').height);$('status').textContent='กำลังโหลด '+v+'…';try{const data=catalog[v];if(!data)throw Error('Unknown view');const loaded=await Promise.all(Object.entries(data.images).map(([n,src])=>new Promise((ok,no)=>{const im=new Image();im.onload=()=>ok([n,im]);im.onerror=()=>no(Error('Missing part '+n));im.src=src})));if(token!==serial)return;D=data;view=v;clock=new SpriteClipClock({durations:D.durations_ms,loop:true});for(const[n,im]of loaded)layers.set(n,new SpriteArticulatedLayer(document.createElement('canvas'),im,D.definitions[n]));frame=0;$('view').value=v;$('travel').checked=false;$('loop').checked=true;$('loop').disabled=false;draw();$('play').disabled=$('frame').disabled=false;window.READY=true;return v}catch(e){if(token!==serial)return;dispose();window.LOAD_ERROR=e.message;$('status').textContent='โหลดไม่ได้: '+e.message}}
function select(i){if(!window.READY)return;clock.cancel();clock.seek(D.durations_ms.slice(0,i).reduce((a,b)=>a+b,0));frame=i;draw()}
$('frame').oninput=()=>select(+$('frame').value);$('view').onchange=()=>choose($('view').value);$('play').onclick=()=>{if(!window.READY)return;if(clock.running)clock.cancel();else{clock.clip.loop=$('loop').checked;if(clock.finished||clock.time===0)clock.start();else clock.running=true}last=null};$('travel').onchange=()=>{if(!window.READY)return;clock.cancel();if($('travel').checked)$('loop').checked=false;$('loop').disabled=$('travel').checked;clock.seek(0);frame=0;draw()};function tick(now){if(window.READY&&clock.running){frame=clock.advance((last===null?0:Math.max(0,now-last))*+$('speed').value).frame;draw()}last=now;requestAnimationFrame(tick)}
window.study={choose,select,draw,poseAt,get view(){return view},get data(){return D},get clock(){return clock},get layers(){return layers},frame(i){select(i);return $('c').toDataURL('image/png')}};choose('W');requestAnimationFrame(tick);
</script></html>''';(P/'walk-family-review.html').write_text(html.replace('__SCRIPTS__',scripts).replace('__DATA__',json.dumps(catalog,separators=(',',':'))));print('Standalone8-view rig review; no external network requests')
